"""Find the world-map scroll/ribbon banner art in the extracted tile pyramids
and derive labels for the banners the game's `WorldMapPlaceNameParam` does not
name.

    python vendor/elden-ring-map/tools/find_map_banners.py

Writes two files:

    vendor/elden-ring-map/data/map-banners.json        (generated, gitignored)
    public/sourced/open/map-banners.json               (committed copy)

and merges any *derived* labels into the place-name document:

    public/sourced/open/map-place-names.json           (committed copy)
    vendor/elden-ring-map/data/place-names.json        (regenerated by map:setup)

Method
------

The map tiles carry the pale ribbon/scroll banner art but no glyphs; the names
are drawn at runtime. ``WorldMapPlaceNameParam`` ships only nine of those banners
(Limgrave, Liurnia, Caelid, Altus Plateau, Mountaintops of the Giants, Ainsel
River, Deeproot Depths, Siofra River, Realm of Shadow). The banners the param
does not name are still blank.

1. Detect the banner art with normalised cross-correlation against the nine
   known banner crops (the Task 122 brief's first option), run on a high-pass
   ("top-hat") copy of each master so a banner's pale band stands out from the
   terrain tint behind it. A pale, elongated band is accepted as a banner; the
   match score is the confidence. The known nine must be re-found (tested).
2. Name a detected banner from ``BonfireWarpSubCategoryParam`` by taking the
   sub-category whose grace centroid (projected with the same code path as
   ``build_markers.py``) is nearest and within a sane radius. A banner already
   covered by one of the nine shipped labels keeps that name; a banner with no
   nearby centroid is left unlabelled and listed.

Nothing here invents a coordinate: a label is only emitted for a banner that was
actually detected, and only named if a real sub-category centroid reaches it.
"""
import argparse
import json
import math
import os
import re
import sys
from collections import defaultdict

import numpy as np
from PIL import Image

reconfigure = getattr(sys.stdout, "reconfigure", None)
if reconfigure:
    reconfigure(encoding="utf-8")

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)                                   # vendor/elden-ring-map
ALL_KNOWING = os.path.dirname(os.path.dirname(ROOT))
TILES = os.path.join(ROOT, "web", "tiles")
GENERATED = os.path.join(ROOT, "data", "map-banners.json")
COMMITTED = os.path.join(ALL_KNOWING, "public", "sourced", "open", "map-banners.json")
PLACE_GENERATED = os.path.join(ROOT, "data", "place-names.json")
PLACE_COMMITTED = os.path.join(ALL_KNOWING, "public", "sourced", "open", "map-place-names.json")
MARKERS = os.path.join(ROOT, "data", "markers.json")
PARAMDEX = os.path.join(ALL_KNOWING, "public", "sourced", "open", "paramdex")

# Masters that carry banner art (the brief's M00/M10/M01). M11 is a small
# underground inset with no place-name scrolls.
MASTERS = ["M00", "M01", "M10"]
NATIVE_ZOOM = 6
TILE = 256
MASTER_PX = 10496

# Work at 1/4 resolution: a banner is ~800x150 master px, so 200x38 here - ample
# to match, while the full 10496 master would be slow for no gain.
SCALE = 4
SMALL = MASTER_PX // SCALE

# Template window (at SCALE) around a known label. Wide enough to include a full
# banner and its scroll ends, which is what makes the match specific.
TPL_W, TPL_H = 260, 96

# Match score below which a correlation peak is not a banner.
MATCH_MIN = 0.55

# Naming: the sub-category grace centroid must be within this many master px, and
# clearly nearer than the runner-up, or the banner is left unlabelled.
CENTROID_RADIUS = 1800
AMBIGUITY_RATIO = 1.25

# A detected banner within this many px of a shipped WorldMapPlaceNameParam label
# *is* that banner - keep the shipped name, emit no derived duplicate.
KNOWN_MERGE_RADIUS = 700

TIER_MIN_ZOOM = {0: 0.0, 1: 0.7, 2: 1.2, 3: 1.8}


# ----------------------------------------------------------------- image utils

def load_pyramid_mosaic(master: str) -> np.ndarray:
    """Downscaled RGB mosaic of a master from its z=4 tiles, or None."""
    z = 4
    tile_master = TILE * (2 ** (NATIVE_ZOOM - z))              # 1024 master px
    step = tile_master // SCALE                                # 256 px at SCALE
    n = math.ceil(MASTER_PX / tile_master)
    out = Image.new("RGB", (SMALL, SMALL), (0, 0, 0))
    found = 0
    zdir = os.path.join(TILES, master, str(z))
    for tx in range(n):
        for ty in range(n):
            path = os.path.join(zdir, str(tx), str(ty) + ".webp")
            if not os.path.isfile(path):
                continue
            img = Image.open(path).convert("RGB").resize((step, step), Image.BILINEAR)
            out.paste(img, (tx * step, ty * step))
            found += 1
    if not found:
        return None
    return np.asarray(out).astype(np.float32)


def tophat(gray: np.ndarray, sigma: float = 14.0) -> np.ndarray:
    """High-pass the image so the pale band pops out of the terrain tint."""
    from PIL import ImageFilter
    bg = np.asarray(Image.fromarray(gray.astype(np.uint8)).filter(
        ImageFilter.GaussianBlur(sigma))).astype(np.float32)
    return gray - bg


def fft_correlate(a: np.ndarray, t: np.ndarray) -> np.ndarray:
    """Valid-mode cross-correlation of a with t (both 2D), via FFT."""
    h, w = t.shape
    shape = (a.shape[0] + h - 1, a.shape[1] + w - 1)
    fa = np.fft.rfft2(a, shape)
    fb = np.fft.rfft2(t[::-1, ::-1], shape)
    full = np.fft.irfft2(fa * fb, shape)
    return full[h - 1:a.shape[0], w - 1:a.shape[1]]


def _integral(a: np.ndarray) -> np.ndarray:
    s = np.zeros((a.shape[0] + 1, a.shape[1] + 1), np.float64)
    s[1:, 1:] = np.cumsum(np.cumsum(a, 0), 1)
    return s


def _window_sum(ii: np.ndarray, h: int, w: int) -> np.ndarray:
    return ii[h:, w:] - ii[:-h, w:] - ii[h:, :-w] + ii[:-h, :-w]


def match_template(image: np.ndarray, tpl: np.ndarray) -> np.ndarray:
    """Normalised cross-correlation score map (valid mode), in [-1, 1]."""
    h, w = tpl.shape
    t = tpl - tpl.mean()
    tn = float((t * t).sum())
    if tn <= 1e-9:
        return np.full((image.shape[0] - h + 1, image.shape[1] - w + 1), 0.0)
    corr = fft_correlate(image, t)
    ii = _integral(image)
    ii2 = _integral(image * image)
    n = h * w
    s = _window_sum(ii, h, w)
    s2 = _window_sum(ii2, h, w)
    var = np.maximum(s2 - s * s / n, 0.0)
    denom = np.sqrt(var) * math.sqrt(tn)
    with np.errstate(divide="ignore", invalid="ignore"):
        return np.where(denom > 1e-9, corr / denom, 0.0)


def local_maxima(score: np.ndarray, threshold: float, min_dist: int, limit: int = 40):
    """Greedy NMS on a score map -> [(score, x, y)] with x/y in the map frame."""
    ys, xs = np.where(score >= threshold)
    order = np.argsort(-score[ys, xs])
    picked = []
    for k in order:
        x, y = int(xs[k]), int(ys[k])
        if all((x - px) ** 2 + (y - py) ** 2 >= min_dist * min_dist for _, px, py in picked):
            picked.append((float(score[y, x]), x, y))
            if len(picked) >= limit:
                break
    return picked


def band_rect(rep: np.ndarray, x: int, y: int):
    """Bounding box (at SCALE) of the pale band around a peak."""
    x0, x1 = max(0, x - TPL_W), min(rep.shape[1], x + TPL_W)
    y0, y1 = max(0, y - TPL_H), min(rep.shape[0], y + TPL_H)
    win = rep[y0:y1, x0:x1]
    if win.size == 0 or win.max() <= 0:
        return None
    mask = win >= (win.max() * 0.55)
    rows = np.where(mask.any(1))[0]
    cols = np.where(mask.any(0))[0]
    if not len(rows) or not len(cols):
        return None
    return (x0 + int(cols.min()), y0 + int(rows.min()), x0 + int(cols.max()) + 1, y0 + int(rows.max()) + 1)


# ------------------------------------------------------------------- naming

def load_subcategory_names():
    """grace row id -> BonfireWarpSubCategoryParam name, from the Paramdex dump."""
    path = os.path.join(PARAMDEX, "BonfireWarpParam.txt")
    out = {}
    if not os.path.isfile(path):
        return out
    for line in open(path, encoding="utf-8"):
        m = re.match(r"\s*(\d+)\s+\[([^\]]+)\]\s+", line)
        if m:
            out[int(m.group(1))] = m.group(2)
    return out


def subcategory_ids():
    """name -> id from BonfireWarpSubCategoryParam.txt."""
    path = os.path.join(PARAMDEX, "BonfireWarpSubCategoryParam.txt")
    out = {}
    if not os.path.isfile(path):
        return out
    for line in open(path, encoding="utf-8"):
        m = re.match(r"\s*(\d+)\s+(.+?)\s*$", line)
        if m:
            out[m.group(2)] = int(m.group(1))
    return out


def grace_centroids():
    """sub-category name -> {master: (cx, cy, n)} from the projected markers."""
    names = load_subcategory_names()
    if not names:
        return {}
    try:
        markers = json.load(open(MARKERS, encoding="utf-8"))["markers"]
    except (OSError, ValueError):
        return {}
    acc = defaultdict(list)
    for m in markers:
        if m.get("cat") != "grace" or m.get("px") is None:
            continue
        try:
            row = int(str(m["id"]).split(":")[1])
        except (IndexError, ValueError):
            continue
        sub = names.get(row)
        if sub:
            acc[sub].append((m["px"], m["py"], m.get("master")))
    out = {}
    for sub, pts in acc.items():
        by_master = defaultdict(list)
        for px, py, master in pts:
            by_master[master].append((px, py))
        out[sub] = {
            "byMaster": {
                master: (sum(p[0] for p in ps) / len(ps), sum(p[1] for p in ps) / len(ps), len(ps))
                for master, ps in by_master.items()
            }
        }
    return out


# --------------------------------------------------------------------- detect

def detect(mosaics: dict, known_by_master: dict):
    """-> list of banner detections in master-pixel space.

    Every one of the nine known banner crops is matched against *every* master,
    so a banner whose own region name never shipped can still be found (the
    templates are the ribbon art, not the place).
    """
    reps = {}
    for master in MASTERS:
        img = mosaics.get(master)
        if img is None:
            continue
        gray = np.asarray(Image.fromarray(img.astype(np.uint8)).convert("L")).astype(np.float32)
        reps[master] = tophat(gray)

    # one template per known label, cropped from its own master
    templates = []
    for master, labels in known_by_master.items():
        rep = reps.get(master)
        if rep is None:
            continue
        for label in labels:
            x0 = int(label["px"] / SCALE - TPL_W // 2)
            y0 = int(label["py"] / SCALE - TPL_H // 2)
            if x0 < 0 or y0 < 0 or x0 + TPL_W > rep.shape[1] or y0 + TPL_H > rep.shape[0]:
                continue
            templates.append((label, rep[y0:y0 + TPL_H, x0:x0 + TPL_W]))
    print(f"  templates: {len(templates)}")

    detections = []
    for target, rep in reps.items():
        for label, tpl in templates:
            score = match_template(rep, tpl)
            for s, x, y in local_maxima(score, MATCH_MIN, min_dist=18):
                detections.append({
                    "master": target,
                    "x": x + TPL_W // 2, "y": y + TPL_H // 2, "score": s,
                    "template": label["names"]["en"],
                })
    # merge detections of the same banner (same master, close in px)
    merged = []
    for det in sorted(detections, key=lambda d: -d["score"]):
        if any(d["master"] == det["master"]
               and (d["x"] - det["x"]) ** 2 + (d["y"] - det["y"]) ** 2 < 20 ** 2
               for d in merged):
            continue
        merged.append(det)
    return merged


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--match-min", type=float, default=MATCH_MIN)
    ap.add_argument("--master", default=None, help="debug: only this master")
    args = ap.parse_args()
    globals()["MATCH_MIN"] = args.match_min

    place_doc = None
    for path in (PLACE_GENERATED, PLACE_COMMITTED):
        try:
            place_doc = json.load(open(path, encoding="utf-8"))
            break
        except (OSError, ValueError):
            continue
    if place_doc is None:
        sys.exit("no place-names.json - run map:setup first")

    known_by_master = defaultdict(list)
    for label in place_doc.get("labels", []):
        if label.get("source") == "derived-banner":
            continue
        known_by_master[label["master"]].append(label)
    n_known = sum(len(v) for v in known_by_master.values())
    print(f"known WorldMapPlaceNameParam labels: {n_known}")

    masters = [args.master] if args.master else MASTERS
    mosaics = {}
    for master in masters:
        mosaics[master] = load_pyramid_mosaic(master)
        print(f"  {master}: mosaic {'ok' if mosaics[master] is not None else 'missing'}")

    detections = detect(mosaics, known_by_master)
    print(f"banner detections: {len(detections)}")

    centroids = grace_centroids()
    ids = subcategory_ids()

    banners = []
    unlabeled = []
    used_subs = set()
    for det in detections:
        master = det["master"]
        cx, cy = det["x"] * SCALE, det["y"] * SCALE
        rect = None
        img = mosaics.get(master)
        if img is not None:
            rep = tophat(np.asarray(Image.fromarray(img.astype(np.uint8)).convert("L")).astype(np.float32))
            r = band_rect(rep, det["x"], det["y"])
            if r:
                rect = [r[0] * SCALE, r[1] * SCALE, r[2] * SCALE, r[3] * SCALE]
        if rect is None:
            rect = [cx - 400, cy - 90, cx + 400, cy + 90]

        # is this one of the shipped banners?
        near_known = None
        for label in known_by_master.get(master, []):
            d = math.hypot(label["px"] - cx, label["py"] - cy)
            if d < KNOWN_MERGE_RADIUS:
                near_known = label
                break
        if near_known is not None:
            banners.append({
                "id": near_known["id"], "master": master,
                "px": round(cx, 1), "py": round(cy, 1),
                "rect": [round(v, 1) for v in rect],
                "confidence": round(min(1.0, det["score"]), 3),
                "source": "param-banner",
                "name": near_known["names"]["en"],
                "textId": near_known.get("textId"),
            })
            continue

        # name from the nearest sub-category grace centroid
        best = None
        for sub, info in centroids.items():
            c = info["byMaster"].get(master)
            if not c:
                continue
            d = math.hypot(c[0] - cx, c[1] - cy)
            if best is None or d < best[1]:
                best = (sub, d)
        if best is None or best[1] > CENTROID_RADIUS:
            unlabeled.append({"master": master, "px": round(cx, 1), "py": round(cy, 1),
                              "confidence": round(det["score"], 3), "reason": "no sub-category centroid in range"})
            continue
        second = None
        for sub, info in centroids.items():
            c = info["byMaster"].get(master)
            if not c or sub == best[0]:
                continue
            d = math.hypot(c[0] - cx, c[1] - cy)
            if second is None or d < second:
                second = d
        if second is not None and best[1] * AMBIGUITY_RATIO > second:
            unlabeled.append({"master": master, "px": round(cx, 1), "py": round(cy, 1),
                              "confidence": round(det["score"], 3),
                              "reason": f"ambiguous: {best[0]} d={best[1]:.0f} vs d={second:.0f}"})
            continue
        sub = best[0]
        used_subs.add(sub)
        sub_id = ids.get(sub)
        c = centroids[sub]["byMaster"][master]
        banners.append({
            "id": f"banner:{sub_id}" if sub_id is not None else f"banner:{sub}",
            "master": master, "px": round(cx, 1), "py": round(cy, 1),
            "rect": [round(v, 1) for v in rect],
            "confidence": round(det["score"], 3),
            "source": "derived-banner",
            "name": sub,
            "subCategoryId": sub_id,
            "centroid": [round(c[0], 1), round(c[1], 1), c[2]],
            "distance": round(best[1], 1),
        })

    banners.sort(key=lambda b: (b["master"], -b["confidence"]))
    subcats = sorted(centroids)
    unplaced = [s for s in subcats if s not in used_subs]
    payload = {
        "generatedBy": "vendor/elden-ring-map/tools/find_map_banners.py",
        "source": "template match on the extracted tile pyramids + BonfireWarpSubCategoryParam",
        "masterPx": MASTER_PX,
        "scale": SCALE,
        "matchMin": args.match_min,
        "knownLabels": n_known,
        "banners": banners,
        "unlabeled": unlabeled,
        "unplacedSubcategories": unplaced,
    }
    for path in (GENERATED, COMMITTED):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=1)
            f.write("\n")
        print(f"-> {path}")

    merge_place_names(banners)

    derived = [b for b in banners if b["source"] == "derived-banner"]
    print(f"\nbanners: {len(banners)}  ({len(derived)} derived, "
          f"{len(banners) - len(derived)} shipped)  unlabelled: {len(unlabeled)}")
    for b in banners:
        flag = "derived" if b["source"] == "derived-banner" else "shipped"
        print(f"  {flag:<7} {b['name'][:34]:<36} {b['master']} "
              f"({b['px']:>7.1f},{b['py']:>7.1f})  conf={b['confidence']:.3f}")
    if unlabeled:
        print("unlabelled detections:")
        for u in unlabeled:
            print(f"  {u['master']} ({u['px']},{u['py']}) conf={u['confidence']}: {u['reason']}")
    subcats = sorted(centroids)
    unplaced = [s for s in subcats if s not in used_subs]
    subcats = sorted(centroids)
    unplaced = [s for s in subcats if s not in used_subs]
    print(f"\nsub-categories with a detected banner: {len(used_subs)}/{len(subcats)}")
    print("sub-categories with no detected banner art (left unlabelled):")
    print("  " + ", ".join(unplaced))


def merge_place_names(banners):
    """Fold derived-banner labels into the place-name document (idempotent)."""
    derived = [b for b in banners if b["source"] == "derived-banner"]
    if not derived:
        print("\nno derived banners: place-names.json left unchanged")
        return
    for path in (PLACE_GENERATED, PLACE_COMMITTED):
        try:
            doc = json.load(open(path, encoding="utf-8"))
        except (OSError, ValueError):
            continue
        keep = [l for l in doc.get("labels", []) if l.get("source") != "derived-banner"]
        existing = {l["id"] for l in keep}
        added = 0
        for b in derived:
            if b["id"] in existing:
                continue
            keep.append({
                "id": b["id"],
                "textId": 0,
                "piece": 0,
                "tier": 1,
                "minZoom": TIER_MIN_ZOOM[1],
                "world": "overworld" if b["master"] == "M00" else ("underground" if b["master"] == "M01" else "shadow"),
                "master": b["master"],
                "px": b["px"],
                "py": b["py"],
                "source": "derived-banner",
                "confidence": b["confidence"],
                "names": {"en": b["name"], "ru": b["name"]},
            })
            existing.add(b["id"])
            added += 1
        keep.sort(key=lambda l: (l["master"], l["names"].get("en", "")))
        doc["labels"] = keep
        with open(path, "w", encoding="utf-8") as f:
            json.dump(doc, f, ensure_ascii=False, indent=1)
            f.write("\n")
        print(f"-> {path}  ({added} derived label(s) merged)")


if __name__ == "__main__":
    main()
